1	//! 출력: 기본 목록과 `json.dumps(..., ensure_ascii=False)` 형식의 JSON.
2	
3	use crate::slug::Entry;
4	
5	pub fn render(entries: &[Entry], min_level: u8) -> String {
6	    let mut out = String::new();
7	    for e in entries {
8	        for _ in 0..usize::from(e.level.saturating_sub(min_level)) {
9	            out.push_str("  ");
10	        }
11	        out.push_str("- [");
12	        out.push_str(e.text);
13	        out.push_str("](#");
14	        out.push_str(&e.slug);
15	        out.push_str(")\n");
16	    }
17	    out
18	}
19	
20	/// JSON 문자열 이스케이프: `"` `\` `\b` `\f` `\n` `\r` `\t` 와 나머지 0x00~0x1f 의 `\u00xx`.
21	fn json_escape(s: &str, out: &mut String) {
22	    out.push('"');
23	    for c in s.chars() {
24	        match c {
25	            '"' => out.push_str("\\\""),
26	            '\\' => out.push_str("\\\\"),
27	            '\x08' => out.push_str("\\b"),
28	            '\x0c' => out.push_str("\\f"),
29	            '\n' => out.push_str("\\n"),
30	            '\r' => out.push_str("\\r"),
31	            '\t' => out.push_str("\\t"),
32	            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
33	            c => out.push(c),
34	        }
35	    }
36	    out.push('"');
37	}
38	
39	pub fn render_json(entries: &[Entry]) -> String {
40	    let mut out = String::from("[");
41	    for (i, e) in entries.iter().enumerate() {
42	        if i > 0 {
43	            out.push_str(", ");
44	        }
45	        out.push_str("{\"level\": ");
46	        out.push_str(&e.level.to_string());
47	        out.push_str(", \"text\": ");
48	        json_escape(e.text, &mut out);
49	        out.push_str(", \"slug\": ");
50	        json_escape(&e.slug, &mut out);
51	        out.push('}');
52	    }
53	    out.push_str("]\n");
54	    out
55	}
56	
57	#[cfg(test)]
58	mod tests {
59	    use super::*;
60	
61	    fn entry(level: u8, text: &str) -> Entry<'_> {
62	        Entry {
63	            level,
64	            text,
65	            slug: "s".to_string(),
66	        }
67	    }
68	
69	    #[test]
70	    fn indentation() {
71	        assert_eq!(render(&[entry(6, "t")], 6), "- [t](#s)\n");
72	        assert_eq!(
73	            render(&[entry(6, "t")], 1),
74	            format!("{}- [t](#s)\n", " ".repeat(10))
75	        );
76	    }
77	
78	    #[test]
79	    fn json_format() {
80	        assert_eq!(render_json(&[]), "[]\n");
81	        let got = render_json(&[entry(1, "a\"\\\x01\x08\x1f\t\x7f/é")]);
82	        assert_eq!(
83	            got,
84	            "[{\"level\": 1, \"text\": \"a\\\"\\\\\\u0001\\b\\u001f\\t\x7f/é\", \"slug\": \"s\"}]\n"
85	        );
86	    }
87	}
