1	//! 인자 해석: Python 3.12 argparse(allow_abbrev=False)의 동작을 이 프로그램의 인자 정의에 한해 그대로 따른다.
2	//!
3	//! 인자마다 종류를 정한 다음(`O` 옵션, `A` 인자, `-` 는 `--` 표시) argparse 와 같은 순서로 소비한다.
4	//! 오류와 `-h` 는 만나는 순서대로 처리하고, 남는 인자(extras)는 끝에서 오류가 된다.
5	
6	use crate::pystr;
7	
8	pub const USAGE: &str = "usage: mdtoc [-h] [--min-level N] [--max-level N] [--json] [file]";
9	
10	pub const HELP: &str = "usage: mdtoc [-h] [--min-level N] [--max-level N] [--json] [file]
11	
12	Make a table of contents from Markdown headings.
13	
14	positional arguments:
15	  file             Markdown file (default: standard input)
16	
17	options:
18	  -h, --help       show this help message and exit
19	  --min-level N
20	  --max-level N
21	  --json           print headings as JSON
22	";
23	
24	pub struct Options {
25	    /// 파일 이름 바이트. `-` 는 표준 입력.
26	    pub file: Vec<u8>,
27	    pub min_level: u8,
28	    pub max_level: u8,
29	    pub json: bool,
30	}
31	
32	pub enum Parsed {
33	    Run(Options),
34	    Help,
35	    /// 사용법 오류의 메시지(`mdtoc: error: ` 뒤에 붙는 부분)
36	    Usage(String),
37	}
38	
39	#[derive(Clone, Copy, PartialEq)]
40	enum Act {
41	    Help,
42	    Min,
43	    Max,
44	    Json,
45	}
46	
47	const OPTIONS: [(&str, Act); 5] = [
48	    ("-h", Act::Help),
49	    ("--help", Act::Help),
50	    ("--min-level", Act::Min),
51	    ("--max-level", Act::Max),
52	    ("--json", Act::Json),
53	];
54	
55	fn act_of(name: &str) -> Option<Act> {
56	    OPTIONS.iter().find(|(n, _)| *n == name).map(|&(_, a)| a)
57	}
58	
59	enum Kind<'a> {
60	    /// `--`
61	    Marker,
62	    Positional,
63	    /// 알려진 옵션(이름, 붙은 값). 값의 첫 항목은 `=` 로 붙었는지(argparse 의 sep)
64	    Opt(&'static str, Option<(bool, &'a [u8])>),
65	    /// 알 수 없는 옵션
66	    Unknown,
67	}
68	
69	/// 정규식 `^-\d+$|^-\d*\.\d+$` (`$` 는 끝의 `\n` 하나도 허용). 이 인자 정의에는 음수 모양 옵션이 없다.
70	fn negative_number(arg: &[u8]) -> bool {
71	    let Ok(s) = std::str::from_utf8(arg) else {
72	        return false;
73	    };
74	    let s = s.strip_suffix('\n').unwrap_or(s);
75	    let Some(rest) = s.strip_prefix('-') else {
76	        return false;
77	    };
78	    let digits = |t: &str| t.chars().all(|c| pystr::decimal_value(c).is_some());
79	    if !rest.is_empty() && digits(rest) {
80	        return true;
81	    }
82	    rest.split_once('.')
83	        .is_some_and(|(a, b)| digits(a) && !b.is_empty() && digits(b))
84	}
85	
86	/// argparse 의 `_parse_optional`.
87	fn parse_optional(arg: &[u8]) -> Kind<'_> {
88	    if arg.first() != Some(&b'-') {
89	        return Kind::Positional;
90	    }
91	    let exact = |b: &[u8]| {
92	        OPTIONS
93	            .iter()
94	            .find(|(n, _)| n.as_bytes() == b)
95	            .map(|&(n, _)| n)
96	    };
97	    if let Some(name) = exact(arg) {
98	        return Kind::Opt(name, None);
99	    }
100	    if arg.len() == 1 {
101	        return Kind::Positional;
102	    }
103	    if let Some(eq) = arg.iter().position(|&b| b == b'=') {
104	        if let Some(name) = exact(&arg[..eq]) {
105	            return Kind::Opt(name, Some((true, &arg[eq + 1..])));
106	        }
107	    }
108	    // 약어는 `--` 로 시작하는 인자에만 막혀 있다. `-h` 뒤에 글자가 붙은 `-hx` 는 `-h` 와 값 `x` 로 본다.
109	    if !arg.starts_with(b"--") && arg.starts_with(b"-h") {
110	        return Kind::Opt("-h", Some((false, &arg[2..])));
111	    }
112	    if negative_number(arg) || arg.contains(&b' ') {
113	        return Kind::Positional;
114	    }
115	    Kind::Unknown
116	}
117	
118	fn is_opt(kind: &Kind) -> bool {
119	    matches!(kind, Kind::Opt(..) | Kind::Unknown)
120	}
121	
122	/// 인자 문자열 목록에서 첫 `--` 를 지운다(argparse `_get_values`).
123	fn without_marker<'a>(strs: &[&'a [u8]]) -> Vec<&'a [u8]> {
124	    let mut v = strs.to_vec();
125	    if let Some(i) = v.iter().position(|s| *s == b"--") {
126	        v.remove(i);
127	    }
128	    v
129	}
130	
131	struct Parser<'a> {
132	    args: &'a [Vec<u8>],
133	    kinds: Vec<Kind<'a>>,
134	    opts: Options,
135	    file_done: bool,
136	    /// 해석하지 못한 인자가 있다(끝에서 오류)
137	    extras: bool,
138	}
139	
140	enum Step {
141	    Next(usize),
142	    Help,
143	}
144	
145	impl<'a> Parser<'a> {
146	    fn slice(&self, from: usize, to: usize) -> Vec<&'a [u8]> {
147	        self.args[from..to].iter().map(Vec::as_slice).collect()
148	    }
149	
150	    /// 위치 인자 `file`(nargs='?', 정규식 `-*A?-*`)를 소비하고 새 위치를 돌려준다.
151	    fn consume_positionals(&mut self, start: usize) -> usize {
152	        if self.file_done {
153	            return start;
154	        }
155	        let n = self.args.len();
156	        let mut i = start;
157	        while i < n && matches!(self.kinds[i], Kind::Marker) {
158	            i += 1;
159	        }
160	        if i < n && matches!(self.kinds[i], Kind::Positional) {
161	            i += 1;
162	        }
163	        while i < n && matches!(self.kinds[i], Kind::Marker) {
164	            i += 1;
165	        }
166	        self.file_done = true;
167	        if let Some(first) = without_marker(&self.slice(start, i)).first() {
168	            self.opts.file = first.to_vec();
169	        }
170	        i
171	    }
172	
173	    fn consume_optional(&mut self, start: usize) -> Result<Step, String> {
174	        let n = self.args.len();
175	        let Kind::Opt(first_name, first_explicit) = self.kinds[start] else {
176	            return Ok(Step::Next(start + 1));
177	        };
178	        let mut name = first_name;
179	        let mut explicit = first_explicit.map(|(sep, e)| (sep, e.to_vec()));
180	        let mut tuples: Vec<(Act, Option<Vec<u8>>)> = Vec::new();
181	        let stop;
182	        loop {
183	            let Some(act) = act_of(name) else {
184	                return Ok(Step::Next(start + 1));
185	            };
186	            let takes = matches!(act, Act::Min | Act::Max);
187	            if let Some((sep, exp)) = explicit.take() {
188	                if !takes && name.as_bytes()[1] != b'-' && !exp.is_empty() {
189	                    // `-hh` 처럼 한 대시 옵션이 이어 붙은 꼴
190	                    if sep || exp[0] == b'-' {
191	                        return Err(format!(
192	                            "argument {name}: ignored explicit argument {}",
193	                            quote(&exp)
194	                        ));
195	                    }
196	                    tuples.push((act, None));
197	                    if exp[0] != b'h' {
198	                        // `-x` 는 알 수 없는 옵션이라 extras 로 가고, 앞의 옵션은 그대로 실행된다
199	                        self.extras = true;
200	                        stop = start + 1;
201	                        break;
202	                    }
203	                    name = "-h";
204	                    let rest = &exp[1..];
205	                    explicit = match rest.first() {
206	                        None => None,
207	                        Some(b'=') => Some((true, rest[1..].to_vec())),
208	                        Some(_) => Some((false, rest.to_vec())),
209	                    };
210	                    continue;
211	                } else if takes {
212	                    tuples.push((act, Some(exp)));
213	                    stop = start + 1;
214	                    break;
215	                }
216	                return Err(format!(
217	                    "argument {name}: ignored explicit argument {}",
218	                    quote(&exp)
219	                ));
220	            }
221	            if takes {
222	                // 옵션의 값 패턴은 `A` 하나다(argparse 는 옵션에서 `-*` 를 뺀다). `--` 는 값이 될 수 없다
223	                let next = start + 1;
224	                if next >= n || !matches!(self.kinds[next], Kind::Positional) {
225	                    return Err(format!("argument {name}: expected one argument"));
226	                }
227	                tuples.push((act, Some(self.args[next].clone())));
228	                stop = next + 1;
229	            } else {
230	                tuples.push((act, None));
231	                stop = start + 1;
232	            }
233	            break;
234	        }
235	        for (act, value) in tuples {
236	            match act {
237	                Act::Help => return Ok(Step::Help),
238	                Act::Json => self.opts.json = true,
239	                Act::Min | Act::Max => {
240	                    let flag = if act == Act::Min {
241	                        "--min-level"
242	                    } else {
243	                        "--max-level"
244	                    };
245	                    let level = level_of(flag, &value.unwrap_or_default())?;
246	                    if act == Act::Min {
247	                        self.opts.min_level = level;
248	                    } else {
249	                        self.opts.max_level = level;
250	                    }
251	                }
252	            }
253	        }
254	        Ok(Step::Next(stop))
255	    }
256	}
257	
258	fn quote(bytes: &[u8]) -> String {
