1	//! mdtoc: Markdown 제목으로 목차를 만든다. python_src/mdtoc.py 의 Rust 구현(std 만 사용).
2	
3	mod cli;
4	mod headings;
5	mod pystr;
6	mod render;
7	mod slug;
8	#[rustfmt::skip]
9	mod unicode_tables;
10	
11	use std::ffi::OsStr;
12	use std::fs::File;
13	use std::io::{self, Read, Write};
14	use std::os::unix::ffi::{OsStrExt, OsStringExt};
15	
16	/// 파일 이름을 stderr 에 쓸 문자열로. UTF-8 이 아닌 바이트는 Python 의 backslashreplace 처럼 `\udcXX`.
17	fn display_name(bytes: &[u8]) -> String {
18	    let mut out = String::new();
19	    let mut rest = bytes;
20	    loop {
21	        match std::str::from_utf8(rest) {
22	            Ok(s) => {
23	                out.push_str(s);
24	                return out;
25	            }
26	            Err(e) => {
27	                let (valid, bad) = rest.split_at(e.valid_up_to());
28	                out.push_str(&String::from_utf8_lossy(valid));
29	                let len = e.error_len().unwrap_or(bad.len());
30	                for b in &bad[..len] {
31	                    out.push_str(&format!("\\udc{b:02x}"));
32	                }
33	                rest = &bad[len..];
34	            }
35	        }
36	    }
37	}
38	
39	/// `io::Error` 의 Display 에서 ` (os error N)` 을 뗀 strerror 문구.
40	fn strerror(err: &io::Error) -> String {
41	    let text = err.to_string();
42	    match text.rfind(" (os error ") {
43	        Some(i) => text[..i].to_string(),
44	        None => text,
45	    }
46	}
47	
48	fn read_input(file: &[u8]) -> io::Result<Vec<u8>> {
49	    let mut data = Vec::new();
50	    if file == b"-" {
51	        io::stdin().lock().read_to_end(&mut data)?;
52	    } else {
53	        File::open(OsStr::from_bytes(file))?.read_to_end(&mut data)?;
54	    }
55	    Ok(data)
56	}
57	
58	fn write_stdout(text: &str) {
59	    let _ = io::stdout().lock().write_all(text.as_bytes());
60	}
61	
62	fn fail(message: &str) -> i32 {
63	    let _ = io::stderr().lock().write_all(message.as_bytes());
64	    1
65	}
66	
67	fn run() -> i32 {
68	    let args: Vec<Vec<u8>> = std::env::args_os().skip(1).map(|a| a.into_vec()).collect();
69	    let opts = match cli::parse(&args) {
70	        cli::Parsed::Help => {
71	            write_stdout(cli::HELP);
72	            return 0;
73	        }
74	        cli::Parsed::Usage(message) => {
75	            let _ = io::stderr()
76	                .lock()
77	                .write_all(format!("{}\nmdtoc: error: {message}\n", cli::USAGE).as_bytes());
78	            return 2;
79	        }
80	        cli::Parsed::Run(opts) => opts,
81	    };
82	    let name = if opts.file == b"-" {
83	        "<stdin>".to_string()
84	    } else {
