    ("-h", Act::Help),
    ("--help", Act::Help),
    ("--min-level", Act::Min),
    ("--max-level", Act::Max),
    ("--json", Act::Json),
];

fn act_of(name: &str) -> Option<Act> {
    OPTIONS.iter().find(|(n, _)| *n == name).map(|&(_, a)| a)
